<script lang="ts">
 import Input from '../ui/Input.svelte';import Card from '../ui/Card.svelte';import CardContent from '../ui/CardContent.svelte';import Icon from '../ui/Icon.svelte';
 export type Entry={id:string;displayName:string;firstName:string;lastName:string;workEmail:string|null;departmentName:string|null;designationTitle:string|null};
 let {initialEmployees}:{initialEmployees:Entry[]}=$props();let search=$state('');
 const filteredEmployees=$derived(!search.trim()?initialEmployees:initialEmployees.filter(emp=>[emp.displayName,emp.workEmail,emp.departmentName,emp.designationTitle].some(x=>x?.toLowerCase().includes(search.toLowerCase()))));
</script>
<div class="space-y-6"><div class="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div class="relative w-full max-w-md"><Icon name="Search" class="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted"/><Input type="search" placeholder="Search coworkers by name, department, or title…" bind:value={search} class="pl-9 bg-surface" aria-label="Search directory"/></div><span class="text-xs text-muted font-medium">Showing {filteredEmployees.length} of {initialEmployees.length} team members</span></div>
{#if filteredEmployees.length===0}<Card class="border-border/80 bg-surface shadow-xs"><CardContent class="p-12 text-center space-y-2"><Icon name="Users" class="h-8 w-8 text-slate-400 mx-auto"/><p class="text-sm font-semibold text-foreground">No team members found</p><p class="text-xs text-muted max-w-sm mx-auto">No colleagues matched your search query. Try searching by first name, last name, department, or job title.</p></CardContent></Card>
{:else}<div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{#each filteredEmployees as colleague (colleague.id)}
{@const initials=colleague.displayName?colleague.displayName.split(' ').map(p=>p[0]).filter(Boolean).slice(0,2).join('').toUpperCase():'EM'}
<Card class="border-border/80 bg-surface shadow-xs transition-all hover:border-primary/30 hover:shadow-sm"><CardContent class="p-5 space-y-4"><div class="flex items-start gap-3.5"><div class="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary font-bold text-sm">{initials}</div><div class="min-w-0 flex-1 space-y-0.5"><h3 class="text-sm font-bold text-foreground truncate">{colleague.displayName}</h3><div class="flex items-center gap-1.5 text-xs text-muted truncate"><Icon name="Briefcase" class="h-3 w-3 shrink-0 text-slate-400"/><span class="truncate">{colleague.designationTitle||'Team Member'}</span></div></div></div>
<div class="space-y-2 border-t border-border/50 pt-3 text-xs"><div class="flex items-center gap-2 text-slate-600"><Icon name="Building2" class="h-3.5 w-3.5 shrink-0 text-slate-400"/><span class="truncate">{#if colleague.departmentName}<span class="font-medium text-slate-700">{colleague.departmentName}</span>{:else}<span class="text-muted italic">General Organization</span>{/if}</span></div>
{#if colleague.workEmail}<div class="flex items-center gap-2 text-slate-600"><Icon name="Mail" class="h-3.5 w-3.5 shrink-0 text-slate-400"/><a href={'mailto:'+colleague.workEmail} class="font-mono text-[11px] text-primary hover:underline truncate">{colleague.workEmail}</a></div>{:else}<div class="flex items-center gap-2 text-muted italic"><Icon name="Mail" class="h-3.5 w-3.5 shrink-0 text-slate-300"/><span>No work email listed</span></div>{/if}</div></CardContent></Card>
{/each}</div>{/if}</div>

